param([Parameter(Mandatory)][ValidateSet('r449','r450','r451')][string]$Stage,[Parameter(Mandatory)][string]$Revision)
$ErrorActionPreference='Stop'
$project=Split-Path -Parent $PSScriptRoot
. (Join-Path $PSScriptRoot 'evidence-json.ps1')
$logs=Join-Path $project 'logs\continuation-20261003'
function Pin($p){[ordered]@{path=$p;sha256=(Get-FileHash -LiteralPath $p).Hash;bytes=(Get-Item -LiteralPath $p).Length}}
function Check($p){if((Get-FileHash $p.path).Hash -ne $p.sha256){throw 'Pin drift'};if($p.bytes -and (Get-Item $p.path).Length -ne $p.bytes){throw 'Byte drift'}}
$cp=Join-Path $logs "$Stage-candidate.json";$c=Get-Content $cp -Raw|ConvertFrom-Json;Check $c
foreach($p in $c.source_pins){Check $p;if((Get-FileHash $p.snapshot).Hash -ne $p.sha256){throw 'Source snapshot drift'}}
$build=@(Get-Content (Join-Path $logs "$Revision-library-build.jsonl")|ForEach-Object{try{$_|ConvertFrom-Json}catch{}})
if(-not @($build|Where-Object{$_.reason -eq 'build-finished' -and $_.success}).Count){throw 'Library build incomplete'}
$libs=@($build|Where-Object{$_.reason -eq 'compiler-artifact' -and $_.target.name -eq 'lito_modern'}|ForEach-Object{$_.filenames}|Where-Object{$_ -like '*.rlib'});if($libs.Count -ne 1){throw 'Library count'}
$lib=Join-Path (Split-Path $c.path -Parent) "$Stage-production.rlib";if(!(Test-Path $lib)){[IO.File]::Copy($libs[0],$lib,$false)};if((Get-FileHash $lib).Hash -ne (Get-FileHash $libs[0]).Hash){throw 'Library copy drift'};$c|Add-Member production_library (Pin $lib) -Force
$test=Join-Path $logs "$Revision-consumer.stdout.log";if([IO.File]::ReadAllText($test) -notmatch '1 passed; 0 failed; 0 ignored;'){throw 'Test did not pass'}
$detailPath=Join-Path $logs $(if($Stage -eq 'r449'){'r449-replay-details.json'}elseif($Stage -eq 'r450'){'r450-occlusion-details.json'}else{'r451-terrain-details.json'});$d=Get-Content $detailPath -Raw|ConvertFrom-Json
foreach($p in $d.images){Check $p}
if($d.runtime_inputs_observed -or $d.renderer_LOADED){throw 'Scope escalated'}
$asmPath=Join-Path $logs "$Stage-original-source-pins.json";$asm=Get-Content $asmPath -Raw|ConvertFrom-Json;Check $asm.original_disassembly;$text=[IO.File]::ReadAllText($asm.original_disassembly.path)
foreach($p in $asm.files){Check $p;if(!$text.Contains([IO.File]::ReadAllText($p.path))){throw 'Original ASM fragment differs'}}
$snapPath=Join-Path $logs 'r439-appearance-snapshot.json';$snap=Get-Content $snapPath -Raw|ConvertFrom-Json;$mp=Join-Path $snap.candidate.root 'manifest.json';if((Get-FileHash $mp).Hash -ne $snap.candidate.manifest_sha256){throw 'Resource manifest drift'};$manifest=Get-Content $mp -Raw|ConvertFrom-Json
$resources=@(foreach($name in $d.input_pins.PSObject.Properties.Name){$p=Join-Path $snap.candidate.root $name;$expected=$d.input_pins.$name;$pin=Pin $p;if($pin.sha256 -ne $expected.sha256 -or $pin.bytes -ne $expected.bytes){throw 'Consumed resource drift'};$pin.relative_path=$name;$pin})
$extra=@(foreach($pin in @($d.extra_input_pins)){if($null -ne $pin){Check $pin;$pin}})
& (Join-Path $PSScriptRoot 'audit-continuation-source-scope.ps1')
$scope=Get-Content (Join-Path $logs 'source-change-scope.json') -Raw|ConvertFrom-Json
$claims=if($Stage -eq 'r449'){
 if($d.rows.Count -ne 7 -or $d.rows[6].bank -ne 72 -or $d.rows[6].subframe -ne 0 -or !$d.rows[6].ended -or $d.rows[6].queued_idle -ne 49 -or $d.rows[6].delay_ms -ne 584 -or $d.idle_callback_executed){throw 'Finite replay scope'}
 @('One finite ordinary attack47 Replay joins original clock and full layer preflight; frames1..6 bank88/sub0..5, then endframe0 bank72/sub0.','Selected end body3476-72/shadow3477-72/1056260-72 independently pinned; end has10body/0layer/4shadow source fragments.','28wrong/missing pointer/flags/bank preflights refuse without advancing pending clock. Source-owner/revision/cutoff/default-off and resource SHA guards retained.','Clock1000→1168→1336→1504→1631→1758→1885;endqueuesidle49 due2469/delay584 then refuses further callback. No visible residency or idle execution inferred.','Seven actual body/105/shadow CPU frames replayed in one sequence, final bank72 image differs from bank88 final; image viewed and pinned.')
}elseif($Stage -eq 'r450'){
 if($d.scene_cases -lt 4 -or $d.tie_order_cases -ne 2 -or !$d.actual_prop_reduces_body_visibility -or !$d.actual_tie_reversing_changes_pixels){throw 'Occlusion not proved'}
 @('Actual Native38-0 FirePot scene prop and actual734 attack47 body/shadow/105 resources used in explicit conditional relative placement; no observed world placement asserted.','Original4CD9D0/483770/488860 half-cell scan/depth/newest-first tie rule; behind/same/front placements alter scene visibility with actual prop source depth, without rewriting depths.','Two distinct actual body subframes at same anchor have source-proven equal-depth cell intersections; reverse explicit cross-actor insertion changes covered output pixels. No object-ID ordering or synthetic depth used.','No terrain/roof/player lifetime/Native framebuffer parity/live appearance grant; prop frame0 is an explicit bounded resource sample, not a natural animation default.')
}else{
 if($d.CPU_frames -ne 7 -or $d.rows.Count -ne 7 -or $d.images.Count -ne 7 -or $d.floor_source_references -ne 8192 -or $d.object_source_references -ne 10802 -or $d.idle_callback_executed -or $d.rows[6].bank -ne 72){throw 'Terrain replay scope'}
 @('One finite attack47/end72 sequence now interleaves actual Native564 S32/TIL floor and object source references with actual body/shadow/105 fragments.','8192floor/10802object references from pinned sector7fff8000 and four explicit Native archive roles; encoded/canonical geometry hashes verified by default-off Native resource adapter; no Shared lookup fallback.','Seven distinct selected player states keep R449 clock dispatch/bank/subframe; actor source fragments retain coordinates/depth. Default-off terrain raster caches validated tiles and paints source floor keys then overlay depth keys per scan cell.','Explicit conditional cell32724/32784, static-source roof policy and terrain-before-player insertion; missing policy/position/insertion refused before action step. Seven-frame budget then stops; idle callback remains unexecuted.','Seven512x384 CPU images viewed; current source body visible counts1012,1083,1060,1050,1034,938,807. Full Layer8 animation, actor-driven roof/runtime/global flags/live world placement and appearance owner remain unqualified.')
}
$historyNames=@('r447','r448');if($Stage -in @('r450','r451')){$historyNames+=@('r449')};if($Stage -eq 'r451'){$historyNames+=@('r450')}
$history=@(foreach($name in $historyNames){$p=Join-Path $logs "$name-candidate.json";$old=Get-Content $p -Raw|ConvertFrom-Json;Check $old;Check $old.production_library;foreach($source in $old.source_pins){if((Get-FileHash $source.snapshot).Hash -ne $source.sha256){throw 'Historical snapshot drift'}};[ordered]@{record=Pin $p;preserved=$true;source_copies=$old.source_pins.Count}})
$c.validation='PASSED one new meaningful focused finite renderer consumer; source/host/lib/ASM/resource/output pinned; conditional only'
Write-ModernEvidenceJson -Path $cp -Value $c
$result=Join-Path $logs "$Stage-finite-renderer-result.json"
Write-ModernEvidenceJson -Path $result -Value ([ordered]@{state='PASSED_FINITE_CONDITIONAL_RENDERER_CONTINUATION';checked_at=[DateTimeOffset]::Now.ToString('o');candidate=$c;focused_passed=1;focused_failed=0;test=Pin $test;details=Pin $detailPath;ASM=Pin $asmPath;original_fragments=$asm.files.Count;resource_snapshot=Pin $snapPath;resource_manifest=Pin $mp;selected_resources=$resources;extra_inputs=$extra;claims=$claims;images=$d.images;visual_reviewed=$true;historical_preserved=$history;source_files=$scope.source_files;live_appearance_qualified=$false;original_BIN_executed=$false;idle_callback_executed=$false;renderer_LOADED=$false;GUI=0;R408_changed=$false;overall_status='in_progress'})
$handoff=Join-Path $logs $(if($Stage -eq 'r449'){'Native-appearance-R449有限玩家動作bank72結束交接.txt'}elseif($Stage -eq 'r450'){'Native-appearance-R450真資源場景遮擋與同深度交接.txt'}else{'Native-appearance-R451真地形有限玩家動作交接.txt'})
[IO.File]::WriteAllText($handoff,($claims -join "`r`n")+"`r`nResult: $result`r`n$($c.source_pins.Count)source/$($asm.files.Count)fullASM/$($resources.Count)appearance inputs+$($extra.Count)extra inputs. Conditional runtime flags, source placement and cross-actor insertion only; live appearance owner/override/revision/cutoff unknown. LOADEDfalse/GUI0/16of40. R408 and all historical snapshots/drafts preserved.",[Text.UTF8Encoding]::new($false))
Write-ModernEvidenceJson -Path (Join-Path $logs "$Stage-final-verification.json") -Value ([ordered]@{result=Pin $result;handoff=Pin $handoff;candidate=Pin $cp;details=Pin $detailPath;host=Pin $c.path;library=Pin $lib;source_snapshots=$c.source_pins.Count;original_fragments=$asm.files.Count;resources=$resources;extra_inputs=$extra;images=$d.images;visual_reviewed=$true;source_files=$scope.source_files;renderer_LOADED=$false;GUI=0})
$statusPath=Join-Path (Split-Path $project -Parent) '監製進度.json';$status=Get-Content $statusPath -Raw|ConvertFrom-Json
$status.updated_at=[DateTimeOffset]::Now.ToString('o');$status.phase="$Stage finite renderer study passed,live authority pending";$status.current_task="$Stage 1new focused passed; $($claims -join ' ') $($c.source_pins.Count)source/$($asm.files.Count)ASM/$($resources.Count)appearance resources+$($extra.Count)extra inputs pinned and CPU viewed. $($scope.source_files)src/R408 unchanged; historical snapshots/drafts retained. Live override authority still unknown; no old live suite rerun;LOADEDfalse/GUI0/16of40."
$status|Add-Member "${Stage}_finite_renderer" (Pin $result) -Force
Write-ModernEvidenceJson -Path $statusPath -Value $status
Write-Output "$Stage sealed: finite renderer/source/resource/CPU; live still unqualified"
